import unittest
from solution import Uploader, UploadError


class Storage:
    def __init__(self): self.items = {}
    def get(self, key): return self.items.get(key)
    def put(self, key, content, metadata):
        self.items[key] = {'url': 'mem://' + key, 'content': content, 'metadata': metadata}
        return self.items[key]['url']


class Scanner:
    def __init__(self, clean=True): self.clean = clean; self.calls = 0
    def is_clean(self, content): self.calls += 1; return self.clean


class TestUpload(unittest.TestCase):
    def test_upload_and_deduplicate(self):
        storage, scanner = Storage(), Scanner()
        uploader = Uploader(storage, scanner)
        first = uploader.upload(b'abc', 'a.txt', 'text/plain')
        second = uploader.upload(b'abc', 'other.txt', 'text/plain')
        self.assertEqual(first['url'], second['url'])
        self.assertTrue(first['is_new'])
        self.assertFalse(second['is_new'])
        self.assertEqual(len(storage.items), 1)

    def test_validation_and_scan(self):
        with self.assertRaises(UploadError): Uploader(Storage(), Scanner()).upload(b'', 'a', 'x')
        with self.assertRaises(UploadError): Uploader(Storage(), Scanner(), 2).upload(b'abc', 'a', 'x')
        storage, scanner = Storage(), Scanner(False)
        with self.assertRaises(UploadError): Uploader(storage, scanner).upload(b'x', 'a', 'x')
        self.assertEqual(storage.items, {})


if __name__ == '__main__':
    unittest.main()
